commands.command:
cat > /etc/nginx/conf.d/inventory.conf <<'NGINXEOF'
upstream inventory_backends {
    server 10.100.137.11:8080 max_fails=2 fail_timeout=10s;
    server 10.100.137.12:8080 max_fails=2 fail_timeout=10s;
    keepalive 16;
}

server {
    listen 80 default_server;
    listen [::]:80 default_server;
    server_name _;

    location / {
        proxy_pass http://inventory_backends;
        proxy_http_version 1.1;
        proxy_set_header Connection "";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_next_upstream error timeout http_502 http_503 http_504;
    }
}
NGINXEOF
rm -f /etc/nginx/conf.d/default.conf
setsebool -P httpd_can_network_connect 1
nginx -t
systemctl enable --now nginx.service
firewall-cmd --permanent --add-service=http
firewall-cmd --add-service=http

